INSERT INTO `products` (`id`, `name`, `slug`, `sku`, `description`, `price`, `compare_price`, `stock`, `active`, `featured`, `catalog_visible`, `age_min_months`, `age_max_months`, `age_source`, `safety`, `material`, `brand`, `source`, `legacy_data`, `created_at`, `updated_at`, `demo_data`) VALUES ('31', 'Torre de Pelotas Rana', 'torre-de-pelotas-rana', 'ISA-MONT-001', 'Torre en espiral con canasta de rana: el bebé lanza las pelotas y las ve rodar piso por piso.\nEstimula la coordinación mano-ojo, el seguimiento visual y la relación causa-efecto.\nIncluye la torre y pelotas de colores.', '89.00', '119.00', '20', '1', '1', '1', '12', '36', 'Caja del producto: 12m+', NULL, 'Plástico', NULL, 'catalogo-angular', NULL, '2026-10-19 15:03:36', '2026-10-19 16:19:09', '1');
INSERT INTO `products` (`id`, `name`, `slug`, `sku`, `description`, `price`, `compare_price`, `stock`, `active`, `featured`, `catalog_visible`, `age_min_months`, `age_max_months`, `age_source`, `safety`, `material`, `brand`, `source`, `legacy_data`, `created_at`, `updated_at`, `demo_data`) VALUES ('33', 'Kit Sensorial para Bebé', 'kit-sensorial-para-bebe', 'ISA-CAR-003', 'Set de estimulación temprana: sonajero en blanco y negro, pelotas sensoriales con texturas y sonido, libro de tela «Jungle Animals» y mordedor en forma de control remoto.\nPerfecto como regalo de baby shower.', '59.00', NULL, '17', '1', '1', '1', '0', '24', 'Empaques: 0m+ y 3+ meses', NULL, NULL, NULL, 'catalogo-angular', NULL, '2026-10-19 15:03:36', '2026-10-19 16:43:42', '1');
INSERT INTO `products` (`id`, `name`, `slug`, `sku`, `description`, `price`, `compare_price`, `stock`, `active`, `featured`, `catalog_visible`, `age_min_months`, `age_max_months`, `age_source`, `safety`, `material`, `brand`, `source`, `legacy_data`, `created_at`, `updated_at`, `demo_data`) VALUES ('34', 'Peluche Mono Sensorial Happy Monkey', 'peluche-mono-sensorial', 'ISA-BEBE-004', 'Peluche suave con etiquetas de colores y diferentes texturas para explorar con las manitos.\nAcompaña el apego y estimula el tacto y la vista desde los primeros meses.', '69.00', '89.00', '24', '1', '1', '1', '0', '24', 'Producto para bebés (datos de prueba)', NULL, 'Felpa', 'Happy Monkey', 'catalogo-angular', NULL, '2026-10-19 15:03:36', '2026-10-19 16:19:09', '1');
INSERT INTO `products` (`id`, `name`, `slug`, `sku`, `description`, `price`, `compare_price`, `stock`, `active`, `featured`, `catalog_visible`, `age_min_months`, `age_max_months`, `age_source`, `safety`, `material`, `brand`, `source`, `legacy_data`, `created_at`, `updated_at`, `demo_data`) VALUES ('35', 'Bloques de Madera ABC · 27 piezas', 'bloques-de-madera-abc', 'ISA-BLOCK-005', 'Juega, crea, aprende y diviértete: 27 cubos de madera con letras, números y dibujos.\nPara construir torres, reconocer letras y desarrollar la motricidad fina. Vienen en su caja de madera.', '79.00', '109.00', '12', '1', '1', '1', '36', '71', 'SIMULADO PARA PRUEBAS. No es recomendación del fabricante.', NULL, 'Madera', NULL, 'catalogo-angular', NULL, '2026-10-19 15:03:36', '2026-10-19 16:19:09', '1');
INSERT INTO `products` (`id`, `name`, `slug`, `sku`, `description`, `price`, `compare_price`, `stock`, `active`, `featured`, `catalog_visible`, `age_min_months`, `age_max_months`, `age_source`, `safety`, `material`, `brand`, `source`, `legacy_data`, `created_at`, `updated_at`, `demo_data`) VALUES ('36', 'Pesca Dinosaurio Magnética', 'pesca-dinosaurio-magnetica', 'ISA-DINO-006', '¡Diversión que atrapa y enseña! Juego de pesca magnético de madera con forma de dinosaurio.\nMejora la coordinación mano-ojo, estimula la concentración y la paciencia, y ayuda a reconocer colores.\nIncluye: 1 base de dinosaurio, 10 peces magnéticos de colores y 2 cañas de pescar.\nIdeal para jugar en familia o con amigos. Aprendizaje sin pantallas.', '55.00', NULL, '10', '1', '1', '1', '36', '71', 'Caja del producto: 3+', NULL, 'Madera', 'Ohye', 'catalogo-angular', NULL, '2026-10-19 15:03:36', '2026-10-19 16:19:09', '1');
